$ErrorActionPreference='Stop'
function Read-EphemeralSecret([string]$Prompt){$secure=Read-Host -Prompt $Prompt -AsSecureString;$pointer=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure);try{return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($pointer)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($pointer)}}
Write-Host 'Zero-network sender/domain onboarding PREPARE. No Cloudflare or DNS mutation is authorized.'
try{$env:BEACON_ALERT_SENDER=Read-EphemeralSecret 'Exact alert sender address (hidden)';$env:BEACON_ALERT_SENDER_APPROVER=Read-Host 'Operator identity (operator:<label>)';$env:BEACON_ALERT_SENDING_DOMAIN_APPROVAL=Read-Host 'Type APPROVE-CHEAPESTRAM-SENDING-DOMAIN';$env:BEACON_ALERT_DNS_IMPACT_REVIEW=Read-Host 'Type ACKNOWLEDGE-DNS-IMPACT after reviewing Bounce/MX, SPF, DKIM and DMARC';$env:BEACON_ALERT_EMAIL_BINDING_APPROVAL=Read-Host 'Type APPROVE-BEACON-ALERT-EMAIL-BINDING to approve proposed name BEACON_ALERT_EMAIL, or leave blank';& node scripts/beacon-gateway-alert-sender-domain-onboarding-prepare.mjs;if($LASTEXITCODE-ne 0){throw 'Sender/domain PREPARE failed.'}}finally{Remove-Item Env:BEACON_ALERT_SENDER -ErrorAction SilentlyContinue;Remove-Item Env:BEACON_ALERT_SENDER_APPROVER -ErrorAction SilentlyContinue;Remove-Item Env:BEACON_ALERT_SENDING_DOMAIN_APPROVAL -ErrorAction SilentlyContinue;Remove-Item Env:BEACON_ALERT_DNS_IMPACT_REVIEW -ErrorAction SilentlyContinue;Remove-Item Env:BEACON_ALERT_EMAIL_BINDING_APPROVAL -ErrorAction SilentlyContinue}
Write-Host 'STOP: PREPARED authorization only. No EXECUTE command exists.'
